function fs_tool_content_data_12() {
    return [

    'child-tax-credit-calculator' => [
        'focus'     => 'child tax credit calculator',
        'secondary' => [ 'child tax credit 2026', 'child tax credit income limit', 'additional child tax credit', 'child tax credit phase out', 'how much is the child tax credit' ],
        'title'     => 'Child Tax Credit Calculator (2026)',
        'meta'      => 'Free child tax credit calculator: estimate your 2026 credit at $2,200 per child, see the income phase-out, and the refundable Additional Child Tax Credit.',
        'excerpt'   => 'Estimate your 2026 Child Tax Credit, including the income phase-out and how much could be refundable even if you owe no tax.',
        'answer'    => 'The 2026 Child Tax Credit is $2,200 per qualifying child under 17, plus $500 for other dependents. It phases out by $50 for every $1,000 of modified adjusted gross income above $200,000 (single) or $400,000 (married filing jointly). Up to $1,700 per child can be refundable through the Additional Child Tax Credit even if you owe no federal tax.',
        'steps'     => [
            'Enter your filing status and modified adjusted gross income (MAGI).',
            'Enter the number of qualifying children under 17 and any other dependents.',
            'Enter your earned income to estimate the refundable portion.',
            'Review your estimated credit, the phase-out reduction, and the maximum refundable amount.',
        ],
        'formula'   => '<p><strong>Total credit = (qualifying children × $2,200) + (other dependents × $500)</strong>.</p><p><strong>Phase-out reduction = $50 × ROUNDUP(MAGI − threshold, to the nearest $1,000)</strong>, where the threshold is $200,000 (single/HOH) or $400,000 (married filing jointly).</p><p><strong>Refundable (ACTC) = the smallest of</strong>: $1,700 × qualifying children, 15% × (earned income − $2,500), or the remaining credit after phase-out.</p>',
        'example'   => '<p>Married filing jointly, $420,000 MAGI, 2 qualifying children:</p><ul><li>Total credit before phase-out: $2,200 × 2 = <strong>$4,400</strong></li><li>MAGI is $20,000 over the $400,000 threshold, so the reduction is $50 × 20 = <strong>$1,000</strong></li><li>Final estimated credit: $4,400 − $1,000 = <strong>$3,400</strong></li></ul>',
        'sections'  => [
            [ 'Who qualifies as a child for this credit', '<p>A qualifying child must be under 17 at the end of the tax year, have a valid Social Security number, live with you for more than half the year, and be claimed as your dependent. A child who turns 17 during the year no longer qualifies for the full credit — they may instead qualify for the smaller $500 credit for other dependents.</p>' ],
            [ 'How the phase-out actually works', '<p>The credit does not disappear all at once. For every $1,000 (or part of $1,000) your MAGI exceeds the threshold, the total credit drops by $50, across all children combined. A family with a very high income can see their credit reduced to zero, but the reduction happens gradually rather than as a sudden cliff.</p>' ],
            [ 'What makes it refundable', '<p>If your tax liability is lower than your Child Tax Credit, the Additional Child Tax Credit (ACTC) lets you receive up to $1,700 per child back as a refund, even with zero tax owed. The refundable amount is capped at 15% of your earned income above $2,500 — families with very low earned income may not be able to claim the full refundable amount even though they qualify for the credit on paper.</p>' ],
            [ 'The $500 credit for other dependents', '<p>Dependents who do not meet the under-17 test — an older child, a disabled adult child, or an elderly parent you support — can still qualify for a flat $500 nonrefundable credit, using the same income phase-out thresholds as the main Child Tax Credit.</p>' ],
        ],
        'terms'     => [
            [ 'Qualifying child', 'A dependent under 17 with a Social Security number who lived with you more than half the year.' ],
            [ 'MAGI', 'Modified adjusted gross income — for most filers, the same as adjusted gross income (AGI).' ],
            [ 'ACTC', 'Additional Child Tax Credit — the refundable portion of the Child Tax Credit, up to $1,700 per child.' ],
            [ 'Schedule 8812', 'The IRS form used to calculate and claim the Child Tax Credit and ACTC on your return.' ],
        ],
        'faqs'      => [
            [ 'How much is the Child Tax Credit for 2026?', '$2,200 per qualifying child under 17, made permanent and indexed for inflation by the One Big Beautiful Bill Act. Other dependents who do not meet the under-17 test can receive a separate $500 credit.' ],
            [ 'What is the income limit for the Child Tax Credit?', 'The credit begins phasing out above $200,000 of MAGI for single filers and $400,000 for married filing jointly, reduced by $50 for every $1,000 over that threshold.' ],
            [ 'Is the Child Tax Credit refundable?', 'Partially. Up to $1,700 per child can be refunded through the Additional Child Tax Credit even if you owe no tax, limited to 15% of your earned income above $2,500.' ],
            [ 'Can I claim the Child Tax Credit for a child who turned 17 this year?', 'No. The child must be under 17 at the end of the tax year to qualify for the $2,200 credit. A child who turns 17 may instead qualify for the $500 credit for other dependents.' ],
            [ 'Does a baby born during the year qualify?', 'Yes. A child born at any point during the tax year, including December 31, qualifies as long as they have a Social Security number and meet the other requirements.' ],
        ],
        'sources'   => [
            [ 'IRS: Child Tax Credit', 'https://www.irs.gov/credits-deductions/individuals/child-tax-credit' ],
            [ 'IRS: Schedule 8812 instructions', 'https://www.irs.gov/forms-pubs/about-schedule-8812-form-1040' ],
        ],
        'related'   => [ 'income-tax-calculator', 'self-employment-tax-calculator', 'salt-deduction-calculator', '401k-early-withdrawal-calculator' ],
    ],

    'salt-deduction-calculator' => [
        'focus'     => 'salt deduction calculator',
        'secondary' => [ 'salt deduction 2026', 'salt tax cap', 'state and local tax deduction limit', 'salt deduction phase out', 'property tax deduction limit' ],
        'title'     => 'SALT Deduction Calculator (2026 Cap)',
        'meta'      => 'Free SALT deduction calculator: see your 2026 state and local tax deduction, the $40,400 cap, and how the phase-out above $505,000 MAGI works.',
        'excerpt'   => 'Calculate your 2026 SALT deduction, including the $40,400 cap and how it phases down for higher incomes.',
        'answer'    => 'The 2026 SALT (state and local tax) deduction cap is $40,400 ($20,200 if married filing separately), covering property tax plus either state income tax or sales tax combined. The cap phases down by 30% of MAGI above $505,000, but never below a $10,000 floor ($5,000 MFS). You can only use this deduction if you itemize instead of taking the standard deduction.',
        'steps'     => [
            'Enter your filing status and modified adjusted gross income (MAGI).',
            'Enter your property tax paid for the year.',
            'Enter your state/local income tax or sales tax paid, whichever is larger.',
            'Confirm whether you are itemizing deductions, then review your capped deduction.',
        ],
        'formula'   => '<p><strong>Combined SALT = property tax + (state/local income tax or sales tax, not both)</strong>.</p><p><strong>2026 cap = $40,400</strong> ($20,200 MFS), reduced by <strong>30% of MAGI above $505,000</strong>, down to a floor of $10,000 ($5,000 MFS).</p><p><strong>Deduction = the smaller of your combined SALT or the applicable cap</strong>, and only counts if you itemize.</p>',
        'example'   => '<p>Single filer, $350,000 MAGI (under the phase-out threshold), $9,000 property tax, $12,000 state income tax:</p><ul><li>Combined SALT: $9,000 + $12,000 = <strong>$21,000</strong></li><li>2026 cap at this income: the full <strong>$40,400</strong> (no phase-out, since MAGI is under $505,000)</li><li>Deduction: the smaller of the two = <strong>$21,000</strong>, fully deductible</li></ul><p>Compare this to a filer with $600,000 MAGI: the cap would be reduced to roughly $12,500 after the 30% phase-out, meaning a large share of their SALT payments would not be deductible.</p>',
        'sections'  => [
            [ 'What counts toward the SALT cap', '<p>The deduction combines three categories, but with a key restriction: property tax (real estate and, in some cases, personal property tax) plus either state and local income tax or state and local sales tax — you choose whichever is larger, not both. Residents of states with no income tax typically use the sales tax option instead.</p>' ],
            [ 'Why the cap exists and how it changed for 2026', '<p>The SALT deduction was capped at $10,000 starting with the 2018 tax year under the Tax Cuts and Jobs Act. The One Big Beautiful Bill Act raised the cap to $40,400 for 2026, with inflation adjustments in future years, while adding an income-based phase-out for higher earners that was not part of the original 2018 cap.</p>' ],
            [ 'The phase-out for higher incomes', '<p>Above $505,000 of MAGI, the cap itself shrinks — not the deduction directly. The cap is reduced by 30 cents for every dollar of MAGI over that threshold, but it never falls below a $10,000 floor ($5,000 for married filing separately), so even very high earners retain at least the old pre-2026 cap amount.</p>' ],
            [ 'Itemizing vs. the standard deduction', '<p>The SALT deduction only matters if your total itemized deductions (SALT, mortgage interest, charitable gifts, and others) exceed your standard deduction. For 2026 the standard deduction is $16,100 (single), $32,200 (married filing jointly), or $24,150 (head of household) — many filers with moderate SALT payments and no mortgage will still come out ahead taking the standard deduction instead.</p>' ],
        ],
        'terms'     => [
            [ 'SALT', 'State and local tax — the combined category of property tax plus state/local income or sales tax.' ],
            [ 'Itemizing', 'Listing out individual deductions (SALT, mortgage interest, charitable gifts) instead of taking the standard deduction.' ],
            [ 'MAGI', 'Modified adjusted gross income, used to determine the SALT cap phase-out for high earners.' ],
        ],
        'faqs'      => [
            [ 'What is the SALT deduction cap for 2026?', '$40,400 for most filers ($20,200 if married filing separately), covering property tax plus either state/local income tax or sales tax. The cap phases down for MAGI above $505,000, with a $10,000 floor.' ],
            [ 'Can I deduct both state income tax and sales tax?', 'No. You choose whichever is larger — state and local income tax, or state and local sales tax — and add that to your property tax. You cannot deduct both income and sales tax in the same year.' ],
            [ 'Does the SALT deduction phase out for high earners?', 'Yes, starting in 2026. The $40,400 cap itself is reduced by 30% of MAGI above $505,000, but it never drops below a $10,000 floor, so the deduction does not disappear entirely even at very high incomes.' ],
            [ 'Is the SALT deduction available if I take the standard deduction?', 'No. SALT is only deductible if you itemize. If your total itemized deductions, including SALT, are less than the standard deduction for your filing status, the standard deduction is the better choice.' ],
            [ 'What if I live in a state with no income tax?', 'You can still deduct property tax plus state and local sales tax paid, up to the same $40,400 cap — the sales tax option exists specifically for residents of no-income-tax states.' ],
        ],
        'sources'   => [
            [ 'IRS: Topic no. 503, deductible taxes', 'https://www.irs.gov/taxtopics/tc503' ],
            [ 'IRS Revenue Procedure 2025-32 (2026 inflation adjustments)', 'https://www.irs.gov/pub/irs-drop/rp-25-32.pdf' ],
        ],
        'related'   => [ 'income-tax-calculator', 'property-tax-calculator', 'child-tax-credit-calculator', 'self-employment-tax-calculator' ],
    ],

    'senior-deduction-calculator' => [
        'focus'     => 'senior deduction calculator',
        'secondary' => [ 'senior tax deduction 2026', '$6000 senior deduction', 'OBBBA senior bonus deduction', 'senior deduction phase out', 'extra deduction for seniors 65' ],
        'title'     => 'Senior $6,000 Deduction Calculator (2026)',
        'meta'      => 'Free senior deduction calculator: see your 2026 OBBBA $6,000 bonus deduction for age 65+, how the income phase-out works, and your real tax savings.',
        'excerpt'   => 'Enter your age, filing status and income to see your 2026 senior bonus deduction, how much of it phases out, and roughly what it saves you in tax.',
        'answer'    => 'For tax years 2025 through 2028, filers 65 or older get an extra $6,000 deduction per qualifying person, on top of the regular standard deduction and the existing age-65 add-on. It phases out at 6% of MAGI above $75,000 (single, head of household, or married filing separately) or $150,000 (married filing jointly or qualifying surviving spouse), reaching zero once the reduction equals the full $6,000 per person.',
        'steps'     => [
            'Select your filing status.',
            'Check the box if you (and your spouse, on a joint return) will be 65 or older by December 31, 2026.',
            'Enter your modified adjusted gross income (MAGI).',
            'Review your deduction before and after the phase-out, and the estimated tax savings at your bracket.',
        ],
        'formula'   => '<p><strong>Base deduction = $6,000 x number of qualifying people</strong> (you, and your spouse if filing jointly and also 65+).</p><p><strong>Phase-out = 6% x (MAGI − threshold)</strong>, where the threshold is $75,000 for single/head of household/married filing separately, or $150,000 for married filing jointly/qualifying surviving spouse. The reduction cannot exceed the base deduction.</p><p><strong>Your deduction = base deduction − phase-out</strong>, floored at $0.</p>',
        'example'   => '<p>Single filer, 68 years old, $90,000 MAGI:</p><ul><li>Base deduction: <strong>$6,000</strong> (one qualifying person)</li><li>Excess over the $75,000 threshold: $90,000 − $75,000 = <strong>$15,000</strong></li><li>Phase-out: 6% x $15,000 = <strong>$900</strong></li><li>Actual deduction: $6,000 − $900 = <strong>$5,100</strong></li></ul><p>At a 22% marginal rate, that $5,100 deduction is worth about <strong>$1,122</strong> in reduced tax — not $6,000. A married couple where both spouses are 65+ and MAGI is $150,000 or less gets the full $12,000 with no reduction at all, since their threshold is double.</p>',
        'sections'  => [
            [ 'This is a new, separate deduction — not a replacement for the existing one', '<figure style="margin:20px 0;text-align:center"><svg viewBox="0 0 680 170" width="100%" style="max-width:600px;height:auto;font-family:-apple-system,Segoe UI,Roboto,sans-serif"><title>How the three deductions stack for a senior filer</title><desc>Regular standard deduction, plus the existing age-65 add-on, plus the new $6,000 OBBBA senior bonus deduction, stack on top of each other.</desc><rect x="0" y="0" width="680" height="170" rx="20" fill="#F8FAFC"/><rect x="24" y="30" width="190" height="100" rx="14" fill="#FFFFFF" stroke="#00C896" stroke-width="2"/><text x="119" y="68" text-anchor="middle" font-size="13" font-weight="800" fill="#0F172A">1. Regular standard</text><text x="119" y="86" text-anchor="middle" font-size="13" font-weight="800" fill="#0F172A">deduction</text><text x="119" y="108" text-anchor="middle" font-size="10.5" fill="#64748B">everyone gets this</text><text x="226" y="86" text-anchor="middle" font-size="18" fill="#94A3B8">+</text><rect x="245" y="30" width="190" height="100" rx="14" fill="#FFFFFF" stroke="#3B82F6" stroke-width="2"/><text x="340" y="68" text-anchor="middle" font-size="13" font-weight="800" fill="#0F172A">2. Age-65 add-on</text><text x="340" y="86" text-anchor="middle" font-size="10.5" fill="#64748B">existing, unrelated</text><text x="340" y="104" text-anchor="middle" font-size="10.5" fill="#64748B">to OBBBA</text><text x="448" y="86" text-anchor="middle" font-size="18" fill="#94A3B8">+</text><rect x="466" y="30" width="190" height="100" rx="14" fill="#FFFFFF" stroke="#F59E0B" stroke-width="2"/><text x="561" y="68" text-anchor="middle" font-size="13" font-weight="800" fill="#0F172A">3. $6,000 senior</text><text x="561" y="86" text-anchor="middle" font-size="13" font-weight="800" fill="#0F172A">bonus (OBBBA)</text><text x="561" y="108" text-anchor="middle" font-size="10.5" fill="#64748B">new, 2025-2028, phases out</text></svg></figure><p>This is the single biggest point of confusion people have about this deduction, and it is worth being precise about: the $6,000 senior bonus is new, temporary (2025 through 2028 only), and it <strong>stacks on top of</strong> deductions you already get — it does not replace them. Every filer already gets the regular standard deduction, and filers 65 or older already get an additional "age-65 add-on" to that standard deduction, which has existed for decades and has nothing to do with the One Big Beautiful Bill Act. The new $6,000 is a third, separate layer on top of both of those. If you use tax software or a worksheet that only shows you one combined "standard deduction" number, the $6,000 should already be folded into it for 2025-2028 — but if you are estimating by hand from an older worksheet, do not forget to add it separately.</p>' ],
            [ 'The phase-out threshold depends on who in the household qualifies', '<p>This is the second source of real confusion, and it is the reason different calculators online disagree on the numbers. The 6% phase-out is calculated per qualifying person, against a household MAGI threshold that depends on filing status — not a single flat number for every senior.</p><ul><li>Single, head of household, or married filing separately: the deduction starts phasing out at <strong>$75,000 MAGI</strong> and reaches zero at <strong>$175,000</strong> (since $6,000 ÷ 6% = $100,000 of room above the threshold).</li><li>Married filing jointly or qualifying surviving spouse, with <strong>one</strong> spouse 65+: phase-out starts at <strong>$150,000</strong> and the $6,000 reaches zero at <strong>$250,000</strong>.</li><li>Married filing jointly, with <strong>both</strong> spouses 65+: the threshold is still $150,000, but the base deduction is $12,000, so it does not reach zero until <strong>$350,000</strong> — twice the deduction takes twice the phase-out room to erase.</li></ul><p>That third row is exactly why some sources online cite "$250,000" as the cutoff for joint filers and others cite "$350,000" — both are correct, just for different households.</p>' ],
            [ 'A deduction is not a dollar-for-dollar tax cut', '<p>A $6,000 deduction lowers your <em>taxable</em> income by $6,000 — it does not lower your tax bill by $6,000. Your actual savings equal the deduction multiplied by your marginal tax rate. In the worked example above, a filer in the 22% bracket who gets the full $6,000 saves about $1,320, not $6,000. A filer in the 12% bracket with the same deduction saves only about $720. The calculator above shows this estimated dollar savings, not just the deduction amount, so you can see the real impact.</p>' ],
            [ 'Does Social Security income count toward the MAGI used here?', '<p>Yes, generally. The MAGI used for this phase-out includes your adjusted gross income plus certain add-backs, and for most retirees that includes the taxable portion of Social Security benefits (which can be 0%, 50%, or up to 85% of your benefit, depending on your overall income — see our <a href="/average-social-security-check-by-age/">guide to average Social Security benefits</a> for how that taxable-portion calculation works). This matters because a retiree who feels "low income" on a cash-flow basis can still have a MAGI high enough to trigger some phase-out once pension income, required IRA withdrawals, and taxable Social Security are all added together.</p>' ],
            [ 'Who actually benefits most from this deduction', '<p>The deduction is most valuable to middle-income retirees who take the standard deduction rather than itemizing — it is available either way, unlike deductions such as SALT that require itemizing. A retired couple living mostly on Social Security and a modest pension, with MAGI well under $150,000, gets the full benefit. High earners still working past 65, or those with large required retirement-account withdrawals pushing MAGI past $175,000-$350,000 depending on filing status, will see it shrink or disappear — but they are also the group least likely to need it.</p>' ],
        ],
        'terms'     => [
            [ 'MAGI', 'Modified adjusted gross income — your AGI with certain deductions added back; used to test phase-out thresholds on many tax provisions.' ],
            [ 'Phase-out', 'A gradual reduction of a deduction or credit as income rises, rather than an all-or-nothing cutoff.' ],
            [ 'Age-65 add-on', 'The existing, separate extra standard-deduction amount for filers 65+, which predates OBBBA and still applies on top of the new $6,000 bonus.' ],
            [ 'Above-the-line deduction', 'A deduction you can take whether you itemize or use the standard deduction — the senior bonus deduction works this way.' ],
        ],
        'faqs'      => [
            [ 'What is the $6,000 senior deduction?', 'A new federal income tax deduction of $6,000 per person age 65 or older, available for tax years 2025 through 2028 under the One Big Beautiful Bill Act (OBBBA). It is separate from, and in addition to, the regular standard deduction and the existing age-65 add-on.' ],
            [ 'Do I have to itemize to claim it?', 'No. This deduction is available whether you itemize or take the standard deduction, which makes it different from deductions like SALT or mortgage interest that require itemizing.' ],
            [ 'What income counts for the phase-out?', 'Modified adjusted gross income (MAGI), which for most retirees includes wages, pension and retirement-account withdrawals, investment income, and the taxable portion of Social Security benefits.' ],
            [ 'At what income does the deduction disappear completely?', 'For single, head of household, or married filing separately, it reaches zero at $175,000 MAGI. For married filing jointly with one qualifying spouse, it reaches zero at $250,000. For married filing jointly with both spouses 65+, it reaches zero at $350,000, since the starting deduction is twice as large.' ],
            [ 'Is this the same as the existing extra standard deduction for seniors?', 'No. The regular age-65 add-on to the standard deduction already existed before this law and still applies. The $6,000 is a new, separate, temporary deduction that stacks on top of it.' ],
            [ 'Does this deduction expire?', 'Yes. It applies only to tax years 2025 through 2028. Unless Congress passes new legislation, it will not be available for tax year 2029 and beyond.' ],
            [ 'How much will this actually save me in tax?', 'Your deduction amount multiplied by your marginal tax rate, not the full deduction itself. A $6,000 deduction saves about $1,320 at a 22% marginal rate, or about $720 at a 12% rate — the calculator above estimates this for you.' ],
            [ 'Can both spouses claim it on a joint return?', 'Yes, if both are 65 or older, you get $12,000 combined ($6,000 each) before any phase-out, tested against the same $150,000 MFJ threshold.' ],
            [ 'Do I need to be retired to claim this deduction?', 'No. The deduction is based purely on age (65 by the end of the tax year) and income, not on whether you are still working or have retired.' ],
            [ 'Where do I claim this deduction on my tax return?', 'It is claimed as part of your Form 1040 filing for the applicable tax year, using the supporting schedule the IRS provides for senior and dependent-related deductions; check the current-year 1040 instructions for the exact line and form references, since forms can be updated between tax years.' ],
            [ 'Does this affect whether Social Security is taxed?', 'Not directly — the taxability of Social Security benefits is calculated first, under its own separate rules, and that taxable amount then flows into the MAGI used for this deduction\'s phase-out. The two are connected through MAGI but calculated separately.' ],
            [ 'I turn 65 partway through 2026 — do I qualify?', 'Yes. The test is whether you are 65 or older by December 31 of the tax year, so turning 65 at any point during 2026 qualifies you for the full deduction for that year, subject to the income phase-out.' ],
        ],
        'sources'   => [
            [ 'Statute: 26 U.S.C. §151(d)(5)(C)', 'https://uscode.house.gov/view.xhtml?req=granuleid:USC-prelim-title26-section151' ],
            [ 'IRS: forms and instructions', 'https://www.irs.gov/forms-instructions' ],
        ],
        'related'   => [ 'income-tax-calculator', 'social-security-cola-calculator', '401k-early-withdrawal-calculator', 'retirement-savings-calculator' ],
    ],

    'auto-loan-interest-deduction-calculator' => [
        'focus'     => 'auto loan interest deduction calculator',
        'secondary' => [ 'car loan interest deduction 2026', 'OBBBA auto loan deduction', 'new car loan tax deduction', 'auto loan interest deduction phase out', 'is car loan interest tax deductible' ],
        'title'     => 'Auto Loan Interest Deduction Calculator (2026)',
        'meta'      => 'Free auto loan interest deduction calculator: see your 2026 OBBBA car loan interest deduction, the $10,000 cap, eligibility rules, and real tax savings.',
        'excerpt'   => 'Enter your auto loan interest, income and vehicle details to see your 2026 car loan interest deduction and the income phase-out.',
        'answer'    => 'For tax years 2025 through 2028, interest paid on a loan for a new, personal-use vehicle with final U.S. assembly can be deducted up to $10,000 per year, whether or not you itemize. It phases out $200 for every $1,000 of MAGI above $100,000 (single) or $200,000 (married filing jointly), reaching zero at $150,000 and $250,000.',
        'steps'     => [
            'Enter your filing status and the auto loan interest you paid this year.',
            'Enter your modified adjusted gross income (MAGI).',
            'Check the eligibility boxes: new vehicle, personal use, U.S. final assembly, under 14,000 lbs, loan originated after December 31, 2024.',
            'Review your eligible interest, the phase-out, your final deduction and estimated tax savings.',
        ],
        'formula'   => '<p><strong>Eligible interest = the smaller of interest actually paid or $10,000</strong> per year.</p><p><strong>Phase-out = $200 x number of $1,000 increments</strong> (or part of one) that your MAGI is above the threshold — $100,000 for single/head of household/married filing separately, $200,000 for married filing jointly/qualifying surviving spouse.</p><p><strong>Your deduction = eligible interest − phase-out</strong>, floored at $0, and only if the vehicle and loan meet all five eligibility rules.</p>',
        'example'   => '<p>Single filer, $115,000 MAGI, $4,200 of auto loan interest paid on an eligible new, U.S.-assembled vehicle:</p><ul><li>Eligible interest (under the $10,000 cap): <strong>$4,200</strong></li><li>Excess over the $100,000 threshold: $115,000 − $100,000 = $15,000, which is 15 increments of $1,000</li><li>Phase-out: 15 x $200 = <strong>$3,000</strong></li><li>Final deduction: $4,200 − $3,000 = <strong>$1,200</strong></li></ul><p>At a 24% marginal rate, that $1,200 deduction saves about <strong>$288</strong> in tax. A married couple filing jointly with the same $115,000 combined MAGI would be well under their $200,000 threshold and would deduct the full $4,200 interest instead.</p>',
        'sections'  => [
            [ 'This is new for 2025 — most people have never claimed it before', '<p>Before the One Big Beautiful Bill Act, personal auto loan interest was essentially never deductible — only interest on loans used for a business vehicle was. This new deduction, for tax years 2025 through 2028 only, is a genuine exception carved out for personal-use vehicle loans, but it comes with five conditions that all have to be true at once, not just one or two.</p>' ],
            [ 'All five eligibility rules, and why each one trips people up', '<ul><li><strong>The vehicle must be new, not used.</strong> A certified pre-owned or used car loan does not qualify, even from a dealer.</li><li><strong>Personal use, not business or fleet.</strong> A vehicle used primarily for business already has its interest handled under separate business-expense rules and does not get this deduction too.</li><li><strong>Final assembly must be in the United States.</strong> This is about where the vehicle was physically assembled, not where the brand is headquartered — a foreign-badged vehicle assembled at a U.S. plant can qualify, and a domestic-badged vehicle assembled abroad cannot. Check the vehicle\'s VIN against NHTSA\'s decoder if you are not sure.</li><li><strong>Gross vehicle weight rating under 14,000 lbs.</strong> This covers the vast majority of cars, SUVs and pickup trucks, but excludes heavy-duty commercial trucks.</li><li><strong>The loan must have originated after December 31, 2024.</strong> Refinancing an older loan does not reset this date in your favor if the original loan predates the cutoff — check your specific refinance terms, since treatment of refinanced loans has been a genuinely disputed point among tax professionals.</li></ul>' ],
            [ 'Leases do not qualify — a common and costly mix-up', '<p>This deduction is for loan interest on a vehicle you are financing to own. A lease payment is not loan interest, even though a monthly lease payment can look similar to a loan payment on paper, so lease payments get none of this deduction. If you are choosing between leasing and financing a new vehicle for this reason alone, run the full cost comparison rather than assuming the tax deduction tips the decision — $10,000 of interest at a 24% bracket is worth roughly $2,400, which is real money but rarely large enough by itself to make financing better than a lease that otherwise suits you better.</p>' ],
            [ 'Reporting: Form 1098-VLI and the VIN on Schedule 1-A', '<p>Your lender is required to report the qualifying interest to you (and the IRS) on Form 1098-VLI, similar to how mortgage interest is reported on Form 1098. You then report the vehicle\'s VIN alongside the interest amount on Schedule 1-A when you file. Keep your loan documents and the 1098-VLI together with your other tax records for the year.</p>' ],
            [ 'This stacks with other vehicle costs, but does not replace them', '<p>This deduction is about loan interest only — it has nothing to do with sales tax, registration fees, depreciation, or any EV tax credit you may also be eligible for on the same purchase. If you are buying a new vehicle and financing it, run the numbers on your <a href="/tool/auto-loan-calculator/">auto loan calculator</a> for the payment itself, then use this tool separately to estimate the interest deduction on top of that.</p>' ],
        ],
        'terms'     => [
            [ 'MAGI', 'Modified adjusted gross income — your AGI with certain deductions added back; used to test the phase-out threshold.' ],
            [ 'Above-the-line deduction', 'A deduction available whether you itemize or take the standard deduction.' ],
            [ 'Final assembly', 'Where a vehicle was physically put together, verifiable through its VIN — not the same as where the manufacturer is headquartered.' ],
            [ 'Form 1098-VLI', 'The form your lender issues reporting qualifying vehicle loan interest paid during the year.' ],
        ],
        'faqs'      => [
            [ 'Is car loan interest tax deductible in 2026?', 'Yes, for a new, personal-use vehicle with U.S. final assembly, financed with a loan originated after December 31, 2024, up to $10,000 of interest per year — subject to a phase-out above $100,000 MAGI (single) or $200,000 (married filing jointly). This is new for tax years 2025 through 2028 under the One Big Beautiful Bill Act.' ],
            [ 'Does a used car loan qualify?', 'No. The deduction only applies to loans for new vehicles — certified pre-owned and used vehicles do not qualify, regardless of lender or dealer.' ],
            [ 'Do I need to itemize to claim this deduction?', 'No. It is an above-the-line deduction, available whether you itemize or take the standard deduction.' ],
            [ 'What does "final assembly in the United States" mean?', 'It refers to where the vehicle was physically assembled, which you can verify through its VIN, not the brand\'s country of origin. A foreign automaker\'s U.S.-built model can qualify; a model built entirely overseas cannot, even from a U.S. automaker.' ],
            [ 'Does leasing a car qualify for this deduction?', 'No. Only interest on a loan to purchase the vehicle qualifies — lease payments are not loan interest and get no deduction under this provision.' ],
            [ 'At what income does the deduction disappear completely?', 'For single, head of household, or married filing separately, it phases out completely at $150,000 MAGI. For married filing jointly or a qualifying surviving spouse, it phases out completely at $250,000 MAGI.' ],
            [ 'Does this deduction expire?', 'Yes. It applies only to tax years 2025 through 2028 and will not be available for 2029 and later unless Congress extends it.' ],
            [ 'What if my loan originated before 2025?', 'A loan that originated on or before December 31, 2024 generally does not qualify. Treatment of loans refinanced after that date is a genuinely debated point among tax professionals — ask a tax preparer about your specific situation if you refinanced.' ],
            [ 'Is there a maximum vehicle price for this deduction?', 'The deduction is based on interest paid and capped at $10,000 per year, with no separate vehicle-price limit — but weight (under 14,000 lbs GVWR) and the other four eligibility rules still apply regardless of price.' ],
            [ 'How do I report this on my taxes?', 'Your lender reports qualifying interest on Form 1098-VLI. You report the vehicle\'s VIN along with the interest amount on Schedule 1-A when filing your return.' ],
            [ 'Can I claim this deduction on a vehicle used for work?', 'Only if the vehicle is for personal use. A vehicle used primarily for business follows separate business-expense deduction rules instead, not this provision.' ],
            [ 'Does this apply to electric vehicles?', 'Yes, as long as the EV meets the same five rules — new, personal use, U.S. final assembly, under 14,000 lbs GVWR, and a loan originated after December 31, 2024. This deduction is separate from, and can potentially combine with, any EV purchase tax credit for the same vehicle.' ],
        ],
        'sources'   => [
            [ 'IRS: forms and instructions (Schedule 1-A)', 'https://www.irs.gov/forms-instructions' ],
            [ 'NHTSA: VIN decoder', 'https://vpic.nhtsa.dot.gov/decoder/' ],
        ],
        'related'   => [ 'auto-loan-calculator', 'loan-comparison-calculator', 'income-tax-calculator', 'cash-back-vs-low-apr-calculator' ],
    ],

    'bnpl-credit-score-impact-calculator' => [
        'focus'     => 'BNPL credit score impact calculator',
        'secondary' => [ 'does buy now pay later affect credit score', 'FICO 10 BNPL', 'does Klarna report to credit bureaus', 'does Affirm report to credit bureaus', 'buy now pay later credit score 2026' ],
        'title'     => 'BNPL Credit Score Impact Calculator (2026)',
        'meta'      => 'Free BNPL credit score calculator: see whether Affirm, Klarna, Afterpay or PayPal Pay in 4 actually report to credit bureaus, and your real score impact.',
        'excerpt'   => 'Check whether your BNPL provider reports to the credit bureaus yet, and estimate the real effect open buy-now-pay-later loans could have on your score.',
        'answer'    => 'Most buy-now-pay-later loans still do not affect your credit score, because most providers do not report short-term installment data to the bureaus and most lenders still pull older scoring models that ignore BNPL even when it is reported. Affirm is the main exception: it reports to Experian and TransUnion, and FICO found its new BNPL-aware score moved by about 10 points for most users after opening a new Affirm loan.',
        'steps'     => [
            'Select your main BNPL provider.',
            'Enter how many BNPL loans you currently have open.',
            'Confirm whether you have paid on time so far.',
            'Tell us if you are about to apply for other credit, so we can flag the specific risk that matters for your situation.',
        ],
        'formula'   => '<p>There is no single public formula for FICO 10 BNPL, since FICO has not released the exact scoring weights. What is known: a <strong>new BNPL loan moved scores by about 10 points for over 85% of users</strong> in FICO\'s own study of Affirm data, and <strong>multiple open BNPL loans are grouped together</strong> in the model rather than counted one by one, so opening a second or third loan does not simply multiply the effect.</p><p>Before any of that matters, two conditions both have to be true: <strong>your provider has to report your loan to a credit bureau</strong>, and <strong>your lender has to pull a scoring model that reads BNPL data</strong> (FICO 10 BNPL, FICO 10 T BNPL, or VantageScore 4.0) instead of an older model.</p>',
        'example'   => '<p>Two scenarios using the same facts: you have 2 open Affirm loans, paid on time.</p><ul><li><strong>Your mortgage lender</strong> pulls an older FICO model (2, 4, or 5), which is standard for mortgage underwriting as of 2026 — your BNPL loans have <strong>no effect at all</strong> on that score, even though Affirm reported them.</li><li><strong>An auto lender or fintech personal-loan lender</strong> pulls a newer, BNPL-aware score — your two loans are grouped together and could move that specific score by roughly <strong>5-10 points</strong>, based on FICO\'s published study.</li></ul><p>Same loans, same payment history, two different real-world outcomes — because the scoring model, not just the loan itself, decides whether it counts.</p>',
        'sections'  => [
            [ 'Which BNPL providers actually report to the bureaus right now', '<table><thead><tr><th>Provider</th><th>Reports to bureaus?</th></tr></thead><tbody><tr><td>Affirm</td><td>Yes — reports most loans to Experian and TransUnion</td></tr><tr><td>Klarna (Monthly financing)</td><td>Yes, for this longer-term product specifically</td></tr><tr><td>Klarna (Pay in 4 / Pay in 30 / Pay in Full)</td><td>Mostly not reported historically, though this may be starting to expand — check your own report</td></tr><tr><td>Afterpay</td><td>Not broadly, as of this writing — the clearest holdout</td></tr><tr><td>PayPal Pay in 4</td><td>Not confirmed either way; PayPal has not stated that it reports</td></tr></tbody></table><p>This table reflects provider practices as of late 2026 and can change — BNPL credit reporting is actively evolving, and the CFPB has previously noted that most providers do not report. If you are unsure, pull your own credit report from each bureau (annualcreditreport.com) and look for the account directly rather than guessing.</p>' ],
            [ 'Reporting is only half the story — the scoring model matters just as much', '<p>Even a loan that is reported to the bureaus does nothing to a score unless the lender pulls a scoring model built to read it. FICO released FICO® Score 10 BNPL and FICO® Score 10 T BNPL in mid-2025, offered alongside its existing models at no extra cost — but each lender independently chooses which version to use, and most mortgage lenders in particular still rely on older FICO 2, 4, or 5 models for underwriting, which were not built to read BNPL data at all. This is the single most misunderstood part of BNPL and credit: the loan can be fully reported and still invisible to a specific lender\'s pull.</p>' ],
            [ 'The real risk is rarely the score — it is losing track of payments', '<p>Because each individual BNPL payment is small, it is easy to stack several loans across different retailers without noticing the combined monthly obligation. A missed BNPL payment can be sent to collections and reported as a delinquency exactly like a missed credit card payment, which does real, lasting damage regardless of which scoring model anyone uses. If you are juggling multiple BNPL plans, our <a href="/debt-avalanche-vs-snowball/">debt avalanche vs. snowball guide</a> applies just as well to BNPL balances as to credit cards.</p>' ],
            [ 'If you are about to apply for a mortgage or auto loan', '<p>Ask your loan officer directly which score version they pull. Most mortgage underwriting in 2026 still uses older FICO models that ignore BNPL entirely, so an open Affirm loan paid on time is unlikely to hurt a mortgage application — but some auto lenders and newer fintech personal-loan lenders have already adopted BNPL-aware scoring. If you are also considering consolidating other debt before a big application, see whether that helps or hurts using our <a href="/does-debt-consolidation-hurt-your-credit/">guide to debt consolidation and your credit score</a>.</p>' ],
        ],
        'terms'     => [
            [ 'BNPL', 'Buy now, pay later — a short-term installment loan, typically splitting a purchase into 4 payments over about 6 weeks.' ],
            [ 'FICO 10 BNPL', 'A FICO scoring model released in 2025 that reads buy-now-pay-later account data; lenders must specifically choose to use it.' ],
            [ 'Credit bureau', 'One of the three major consumer reporting agencies — Experian, Equifax, and TransUnion — that compile the data credit scores are built from.' ],
        ],
        'faqs'      => [
            [ 'Does buy now pay later affect your credit score?', 'It can, but only if two things are both true: your BNPL provider reports the loan to a credit bureau, and the lender checking your credit pulls a scoring model built to read that data. Most BNPL activity today still does not meet both conditions.' ],
            [ 'Does Klarna report to credit bureaus?', 'Only for its longer-term "Monthly financing" product. Klarna\'s short-term Pay in 4, Pay in 30, and Pay in Full plans are not reported to Experian or TransUnion.' ],
            [ 'Does Affirm report to credit bureaus?', 'Yes, Affirm reports most of its loans to Experian and TransUnion, making it one of the few major BNPL providers whose activity can actually reach your credit file.' ],
            [ 'Does Afterpay affect your credit score?', 'Not broadly, as of this writing — Afterpay does not widely report short-term installment data to the major credit bureaus.' ],
            [ 'What is FICO 10 BNPL?', 'A credit scoring model FICO released in 2025 specifically designed to read buy-now-pay-later account data. It is optional — each lender decides whether to use it or an older model that ignores BNPL.' ],
            [ 'Will BNPL hurt my chances of getting a mortgage?', 'Probably not directly, since most mortgage underwriting in 2026 still uses older FICO models that do not read BNPL data. Ask your loan officer which score they pull to confirm for your specific application.' ],
            [ 'How many points can a BNPL loan affect my score?', 'FICO\'s own simulated study (modeling its new score against existing Affirm data, not live production scores) found roughly a 10-point movement for most users after a new BNPL loan, when using its BNPL-aware score. Multiple open loans are grouped together in the calculation rather than stacked individually.' ],
            [ 'Does missing a BNPL payment hurt my credit?', 'Yes — a missed payment can be sent to collections and reported as a delinquency just like any other account, regardless of which scoring model a lender uses. This is a bigger risk than the BNPL loan simply existing.' ],
            [ 'How do I know if my BNPL loan is on my credit report?', 'Pull your free credit report from each bureau at annualcreditreport.com and look for the provider\'s name directly. Reporting practices vary by provider and can change, so checking your own report is more reliable than general guidance.' ],
        ],
        'sources'   => [
            [ 'FICO: Unveils Credit Scores That Incorporate Buy Now, Pay Later Data', 'https://investors.fico.com/news-releases/news-release-details/fico-unveils-groundbreaking-credit-scores-incorporate-buy-now' ],
            [ 'Consumer Financial Protection Bureau: Buy Now, Pay Later', 'https://www.consumerfinance.gov/consumer-tools/buy-now-pay-later/' ],
            [ 'AnnualCreditReport.com (official free credit report site)', 'https://www.annualcreditreport.com' ],
        ],
        'related'   => [ 'debt-consolidation-calculator', 'personal-loan-calculator', 'net-worth-calculator', 'debt-to-income-ratio-calculator' ],
    ],

    'estimated-tax-penalty-calculator' => [
        'focus'     => 'estimated tax penalty calculator',
        'secondary' => [ 'underpayment penalty calculator', 'IRS safe harbor rule', 'Form 2210 calculator', 'quarterly estimated tax penalty', '1099 estimated tax penalty' ],
        'title'     => 'Estimated Tax Underpayment Penalty Calculator',
        'meta'      => 'Free estimated tax penalty calculator: check the IRS safe harbor rule, see if you owe an underpayment penalty, and estimate the cost before the Q4 deadline.',
        'excerpt'   => 'Check whether your withholding and estimated payments meet the IRS safe harbor, and estimate your underpayment penalty before the January 15 Q4 deadline.',
        'answer'    => 'You generally avoid the underpayment penalty if your withholding plus timely estimated payments reach the smaller of 90% of this year\'s total tax, or 100% of last year\'s tax (110% if last year\'s AGI was over $150,000). Owing less than $1,000 after withholding and credits avoids the penalty regardless of those percentages.',
        'steps'     => [
            'Enter your estimated total tax for this year.',
            'Enter your total withholding plus estimated payments made so far.',
            'Enter last year\'s total tax and last year\'s AGI.',
            'See your safe harbor target, whether you are covered, and a rough penalty estimate if you are short.',
        ],
        'formula'   => '<p><strong>Safe harbor target = the smaller of (90% x this year\'s tax) or (100% or 110% x last year\'s tax)</strong>. Use 110% of last year\'s tax if last year\'s AGI was over $150,000; otherwise use 100%.</p><p>If your withholding plus timely estimated payments meet or exceed that target, or if you owe less than $1,000 after withholding and credits, you owe no penalty. Otherwise, the IRS calculates the penalty <strong>per quarterly installment</strong>, as simple daily interest on that period\'s specific shortfall, at the federal short-term rate plus 3 percentage points (set and published quarterly) — via Form 2210, not a single flat annual number.</p>',
        'example'   => '<p>A freelancer expects to owe $18,000 in total tax this year, has paid $12,000 through estimated payments so far, and last year owed $15,000 total tax on an AGI of $95,000 (under $150,000, so the 100% test applies):</p><ul><li>90% of this year\'s tax: $18,000 x 0.90 = <strong>$16,200</strong></li><li>100% of last year\'s tax: <strong>$15,000</strong></li><li>Safe harbor target: the smaller of the two = <strong>$15,000</strong></li><li>Paid so far: $12,000 — short of the $15,000 target by <strong>$3,000</strong></li></ul><p>This filer is not covered by the safe harbor and should make a Q4 payment to close some or all of the $3,000 gap before the January 15 deadline — the sooner the gap closes, the less the per-installment penalty accrues.</p>',
        'sections'  => [
            [ 'Why this hits 1099 and gig workers hardest', '<p>Employees generally avoid this entirely because their employer withholds tax throughout the year automatically. Freelancers, gig workers, and anyone with significant 1099 income are responsible for estimating and paying their own tax four times a year — and it is easy to underestimate, especially in a first full year of self-employment when there is no prior-year baseline to compare against. If you are also unsure how self-employment tax itself is calculated separately from this penalty, see our <a href="/tool/self-employment-tax-calculator/">self-employment tax calculator</a> first — the penalty calculator here assumes you already know your total tax liability.</p>' ],
            [ 'The 90/100/110 rule, explained plainly', '<p>The IRS gives you two ways to avoid the penalty, and you only need to hit one of them. The "90% rule" looks forward: pay at least 90% of what you will actually owe this year. The "100%/110% rule" looks backward: pay at least as much as last year\'s total tax (110% if you were a higher earner last year), regardless of how this year turns out. The backward-looking rule is often easier to plan around, since last year\'s number is already known at the start of the year — many self-employed people set their quarterly payments based on last year\'s tax bill specifically because it is a known, fixed target.</p>' ],
            [ 'The $1,000 de minimis rule is an easy win for smaller shortfalls', '<p>Regardless of the percentage tests, if your total shortfall after withholding and credits is under $1,000, there is no penalty at all. This matters most for people with a mix of W-2 withholding and smaller side income — if the side income is modest enough, normal W-2 withholding can sometimes keep the total shortfall under this threshold without any separate estimated payments.</p>' ],
            [ 'Why the "penalty" is really just interest, and why it is not one flat number', '<p>Despite the name, the underpayment penalty functions as interest on money the IRS considers it should have had earlier, calculated separately for each of the four payment periods, not as one number applied to the whole year. If you underpaid Q1 but caught up by Q3, you still owe something for the Q1–Q3 period specifically, even though your year-end numbers might look fine overall. This is why the calculator above gives an illustrative estimate rather than an exact figure — the true number depends on exactly when each shortfall occurred and the specific quarterly rate in effect at the time, and should be confirmed on IRS Form 2210 or by your tax software.</p>' ],
            [ 'What to do before the Q4 deadline', '<p>The fourth and final estimated payment of the year is due January 15 of the following year. If this calculator shows you are short of the safe harbor, making a larger Q4 payment is the most direct fix available before filing — it cannot undo penalty already accruing on earlier quarters, but it stops the Q4 period\'s shortfall from growing further and reduces what you owe when you file. If you consistently underpay each year, consider raising your regular quarterly payment amount going forward, or ask an employer-side spouse to increase W-2 withholding instead, since withholding is treated as paid evenly throughout the year regardless of when it actually happens.</p>' ],
        ],
        'terms'     => [
            [ 'Safe harbor', 'A rule that protects you from a penalty as long as you meet a specific payment threshold, even if you end up owing more tax than expected.' ],
            [ 'AGI', 'Adjusted gross income — your income after certain above-the-line deductions, used to determine whether the 100% or 110% prior-year test applies.' ],
            [ 'Form 2210', 'The IRS form used to calculate the exact underpayment penalty, if any, for a given tax year.' ],
            [ 'De minimis threshold', 'The $1,000 shortfall amount under which no underpayment penalty applies, regardless of the safe harbor percentages.' ],
        ],
        'faqs'      => [
            [ 'How do I avoid the estimated tax underpayment penalty?', 'Pay, through withholding and/or timely estimated payments, at least the smaller of 90% of this year\'s total tax or 100% of last year\'s tax (110% if last year\'s AGI was over $150,000). Owing under $1,000 after withholding also avoids it.' ],
            [ 'What is the safe harbor rule for estimated taxes?', 'It is the IRS rule described above — meeting either the 90%-of-this-year or 100%/110%-of-last-year threshold protects you from the underpayment penalty even if you end up owing significant additional tax when you file.' ],
            [ 'When is the Q4 estimated tax payment due?', 'January 15 of the year following the tax year — for example, January 15, 2027 for the 2026 tax year.' ],
            [ 'What if I owe less than $1,000?', 'No underpayment penalty applies if your total shortfall after withholding and credits, for the year, is under $1,000 — regardless of the percentage safe harbor tests.' ],
            [ 'How is the underpayment penalty calculated?', 'As simple daily interest on each quarterly installment\'s specific shortfall, at the federal short-term rate plus 3 percentage points (a rate set and published quarterly, not fixed for the whole year), using IRS Form 2210.' ],
            [ 'Does this apply to W-2 employees?', 'Rarely, since employer withholding is treated as paid evenly throughout the year and usually covers the safe harbor automatically. It mainly affects people with significant 1099, gig, freelance, rental, or investment income with no withholding.' ],
            [ 'Is 100% or 110% the right test for me?', 'Use 110% of last year\'s total tax if last year\'s AGI was over $150,000 ($75,000 if married filing separately); otherwise use 100%.' ],
            [ 'Can I fix an earlier underpaid quarter by overpaying Q4?', 'Partially. A larger Q4 payment stops that period\'s shortfall from growing, but it does not erase penalty interest that already accrued on an earlier quarter\'s shortfall — only paying that specific quarter on time would have avoided it.' ],
            [ 'Does this calculator give my exact penalty amount?', 'No — it gives an illustrative estimate only. The exact figure depends on the specific timing of each quarter\'s shortfall and the IRS rate in effect each quarter; use IRS Form 2210 or your tax software for the precise number.' ],
        ],
        'sources'   => [
            [ 'IRS: Form 2210, Underpayment of Estimated Tax', 'https://www.irs.gov/forms-pubs/about-form-2210' ],
            [ 'IRS: Estimated taxes', 'https://www.irs.gov/businesses/small-businesses-self-employed/estimated-taxes' ],
        ],
        'related'   => [ 'self-employment-tax-calculator', 'income-tax-calculator', 'tax-bonus-calculator' ],
    ],

    'student-loan-401k-match-calculator' => [
        'focus'     => 'student loan 401k match calculator',
        'secondary' => [ 'SECURE 2.0 student loan match', 'Section 110 student loan 401k', 'employer match student loan payments', 'student loan retirement match 2026' ],
        'title'     => 'Student Loan 401(k) Match Calculator (SECURE 2.0)',
        'meta'      => 'Free SECURE 2.0 student loan 401(k) match calculator: estimate the employer retirement match your student loan payments can earn you in 2026.',
        'excerpt'   => 'See how much employer 401(k) match your student loan payments could earn you under SECURE 2.0, and what that match could be worth by retirement.',
        'answer'    => 'Under SECURE 2.0 Section 110, an employer can choose to treat your qualified student loan payments as if they were 401(k) contributions for matching purposes — so you can earn your employer\'s match without contributing to your 401(k) yourself. The match follows your plan\'s normal formula and cap; it is a new way to earn the existing match, not a separate new benefit amount.',
        'steps'     => [
            'Enter your annual salary and your qualified student loan payments for the year.',
            'Enter your employer\'s match percentage and cap (check your plan documents or ask HR).',
            'Enter how many years until retirement and an expected average return.',
            'Review your estimated match for this year and its rough projected value at retirement.',
        ],
        'formula'   => '<p><strong>Match cap = salary x your plan\'s match cap percentage.</strong> <strong>Match earned = the smaller of (loan payments x match rate) or the match cap.</strong> This mirrors exactly how a normal 401(k) match works — the loan payments simply substitute for your own contribution in the formula, dollar for dollar, up to your plan\'s normal limits.</p>',
        'example'   => '<p>$65,000 salary, a plan that matches 50% up to 5% of salary (a $1,625 match cap), and $4,800 in qualified student loan payments for the year:</p><ul><li>Match cap: $65,000 x 5% = <strong>$3,250</strong> is the contribution level needed to earn the max, and the match itself caps at 50% of that = <strong>$1,625</strong></li><li>Loan payments ($4,800) exceed the $3,250 needed, so the full cap is earned</li><li>Match earned this year: <strong>$1,625</strong>, deposited into the 401(k) as an employer contribution</li></ul><p>Over 25 years at a 7% average return, that single year\'s $1,625 match alone — left untouched and compounding — would grow to roughly <strong>$8,800</strong>, without the employee putting a single additional dollar into the 401(k) that year.</p>',
        'sections'  => [
            [ 'This is optional for employers — check whether your plan actually offers it', '<p>SECURE 2.0 Section 110 gives employers the ABILITY to offer this matching feature; it does not require any employer to adopt it. Many plans, especially smaller ones, have not yet implemented it, partly because the IRS only issued interim guidance in August 2024 (Notice 2024-63) and some plan sponsors are still waiting on further clarity before amending their documents. Before assuming this applies to you, confirm directly with HR or your plan administrator whether your specific 401(k) plan has adopted student loan matching — the calculator above shows what you COULD earn if it has, not a guarantee that it does.</p>' ],
            [ 'The match goes to your retirement account, not your loan balance', '<p>This is the single most common misunderstanding about this benefit. Making a student loan payment does not reduce your loan balance any faster because of this provision — you are still paying your loan exactly as you otherwise would. What changes is that your employer ALSO deposits a matching contribution into your 401(k), calculated as if your loan payment had been a retirement contribution instead. You get the retirement savings boost without having to choose between paying down debt and saving for retirement with the same dollar.</p>' ],
            [ 'Everyone eligible for the regular match must be eligible for this too', '<p>Employers cannot offer this feature selectively — if your plan adopts it, every employee eligible to make regular 401(k) deferrals must also be eligible for the student loan match version, under the same nondiscrimination rules that apply to the regular match. The law covers loans the employee took out to pay qualified higher-education expenses; most legal analysis reads this as covering a loan you took out for your own education or, as the borrower, for a spouse\'s or dependent\'s education too — though final IRS regulations have not fully settled every detail, so confirm with your plan administrator exactly which loans your specific plan recognizes. You generally need to certify your loan payments to your employer each year for the match to be applied.</p>' ],
            [ 'Can you get both the loan match and a regular 401(k) match in the same year?', '<p>Potentially, depending on your plan\'s design and your own cash flow — if your loan payments do not use up your full match cap, you can often still contribute directly to the 401(k) to capture the remainder, as shown in the "not quite capped" note in the calculator above. Whether your specific plan allows combining both in the same year is a plan-design detail worth confirming with HR rather than assuming either way.</p>' ],
        ],
        'terms'     => [
            [ 'Section 110', 'The SECURE 2.0 Act provision letting employers match qualified student loan payments as if they were 401(k) contributions.' ],
            [ 'Qualified student loan payment', 'A payment toward a loan taken out solely to pay for the employee\'s own qualified higher-education expenses.' ],
            [ 'Match cap', 'The maximum percentage of salary an employer will match, regardless of how much is contributed or paid toward a qualifying loan.' ],
        ],
        'faqs'      => [
            [ 'What is the SECURE 2.0 student loan 401(k) match?', 'A provision (Section 110) letting employers treat an employee\'s qualified student loan payments as if they were 401(k) contributions for matching purposes, so the employee can earn the employer match without contributing to the 401(k) directly.' ],
            [ 'Does my employer have to offer this benefit?', 'No. It is optional. Employers may choose to adopt student loan matching, but many plans — especially smaller employers — have not implemented it. Confirm with your HR department or plan administrator.' ],
            [ 'Does the match pay down my student loan?', 'No. The employer match is deposited into your 401(k) retirement account as a normal employer contribution — it has no effect on your loan balance, which you continue paying exactly as before.' ],
            [ 'Can I use this for my spouse\'s or child\'s student loans?', 'Likely yes, if you are the one who took out the loan to pay for their qualified education expenses — most legal analysis of the statute reads it this way, though final IRS regulations have not fully settled every detail. Confirm with your plan administrator which loans your specific plan recognizes.' ],
            [ 'Do I need to tell my employer about my loan payments?', 'Generally yes — most plans require you to certify your qualified student loan payments annually for the match to be applied correctly.' ],
            [ 'Can I get the match from my loan payments and also contribute to my 401(k)?', 'Depending on your plan\'s design, yes — if your loan payments do not use your full match cap, direct 401(k) contributions can often capture the remainder. Confirm with HR whether your specific plan allows combining both.' ],
        ],
        'sources'   => [
            [ 'IRS: Notice 2024-63 (interim guidance on student loan payment matching)', 'https://www.irs.gov/pub/irs-drop/n-24-63.pdf' ],
            [ 'IRS: SECURE 2.0 Act provisions', 'https://www.irs.gov/retirement-plans/secure-2-0-act-of-2022' ],
        ],
        'related'   => [ '401k-calculator', 'retirement-savings-calculator', 'student-loan-calculator', 'compound-interest-calculator' ],
    ],

    '2027-401k-ira-contribution-limit-calculator' => [
        'focus'     => '2027 401k contribution limit calculator',
        'secondary' => [ '2027 IRA contribution limit', '401k catch-up 2027', 'age 60 to 63 super catch-up', 'IRS Notice 2026-66', 'mandatory Roth catch-up 2027' ],
        'title'     => '2027 401(k) & IRA Contribution Limit Calculator',
        'meta'      => 'Free 2027 401(k) and IRA contribution limit calculator: your exact limit by age, including the 60-63 super catch-up and the mandatory Roth catch-up rule.',
        'excerpt'   => 'Enter your age and prior-year wages to see your exact 2027 401(k) or IRA contribution limit, including catch-up tiers and the mandatory Roth catch-up rule.',
        'answer'    => 'For 2027, the IRS set the 401(k)/403(b)/governmental 457/TSP limit at $25,500, with an $8,500 catch-up at age 50+ ($34,000 total) and a higher $11,750 "super" catch-up for ages 60-63 only ($37,250 total). The IRA limit stays at $7,500, with a $1,100 catch-up at 50+. If your 2026 FICA wages topped $155,000, your entire catch-up must be made as Roth (after-tax), not pre-tax.',
        'steps'     => [
            'Enter your age as of December 31, 2027.',
            'Enter your 2026 FICA wages (Box 3 of your W-2) — this determines the mandatory Roth catch-up rule.',
            'Select your plan type: 401(k)/403(b)/457/TSP, or IRA, and how many pay periods remain in the year.',
            'See your exact base limit, catch-up amount, total limit, whether your catch-up must be Roth, and the per-paycheck amount needed to hit the max.',
        ],
        'formula'   => '<p><strong>401(k)/403(b)/457/TSP 2027:</strong> base $25,500. Age 50-59 or 64+: +$8,500 catch-up ($34,000 total). Age 60-63 only: +$11,750 "super" catch-up ($37,250 total), per SECURE 2.0.</p><p><strong>IRA 2027:</strong> base $7,500. Age 50+: +$1,100 catch-up ($8,600 total) — no special 60-63 tier for IRAs.</p><p><strong>Mandatory Roth catch-up:</strong> if your prior-year FICA wages (not current income) exceeded $155,000, your entire catch-up contribution must be designated Roth, under SECURE 2.0 Section 603.</p>',
        'example'   => '<p>A 61-year-old 401(k) participant with $168,000 in 2026 FICA wages:</p><ul><li>Base 2027 limit: <strong>$25,500</strong></li><li>Age 60-63 "super" catch-up: <strong>$11,750</strong> (not the regular $8,500, since they are 60-63)</li><li>Total 2027 limit: <strong>$37,250</strong></li><li>FICA wages ($168,000) exceed the $155,000 threshold, so the full $11,750 catch-up must be contributed as <strong>Roth</strong>, not pre-tax</li></ul><p>Compare that to a 61-year-old earning $95,000: same $37,250 total limit, but their catch-up can still go in pre-tax, since they are under the $155,000 threshold.</p>',
        'sections'  => [
            [ 'The 60-63 "super" catch-up is narrower than most people realize', '<p>This enhanced catch-up, created by SECURE 2.0, is not available to everyone 60 and older — it applies <strong>only</strong> to the calendar years in which you turn 60, 61, 62, or 63. At 64, the catch-up drops back down to the standard $8,500 amount. If you are 59 turning 60 mid-year, you still get the higher catch-up for the full year, since the test is your age by the end of the year — but if you turn 64 mid-year, you lose it for that year, which catches some people off guard right when they were counting on the bigger number.</p>' ],
            [ 'The mandatory Roth catch-up rule that trips up high earners', '<p>Starting with tax years affected by SECURE 2.0 Section 603, anyone whose <strong>prior-year FICA wages</strong> (reported in Box 3 of your W-2 — not your current salary, bonus, or this year\'s income) exceeded $155,000 for 2027 must have their <em>entire</em> catch-up contribution made as Roth, meaning after-tax, with no pre-tax option for that portion. This is a genuinely confusing rule because: it looks backward at last year\'s wages, not this year\'s; it uses FICA wages specifically, not AGI or taxable income; and it applies to the whole catch-up amount, not just the portion above the threshold. Many payroll systems handle this automatically once you cross the line, but it is worth confirming with your plan administrator rather than assuming your contribution election will work as expected.</p>' ],
            [ 'Why IRAs do not get the same 60-63 boost', '<p>The enhanced "super" catch-up created by SECURE 2.0 applies specifically to employer-sponsored plans — 401(k), 403(b), governmental 457, and the federal Thrift Savings Plan. IRAs were left out of this enhancement entirely; the IRA catch-up has been a flat $1,000 historically and is now inflation-indexed to $1,100, with no special boost at any age. If you are 60-63 and want to maximize retirement savings using the higher catch-up, it has to go through an employer plan, not an IRA.</p>' ],
            [ 'How much do you need to contribute per paycheck to hit the max?', '<p>It depends entirely on how many pay periods remain and which total you are aiming for. The calculator above divides your total limit by the number of pay periods you enter — for a biweekly payroll (26 periods) starting January 1, maxing out the standard $34,000 limit (age 50+) takes about $1,307.69 per paycheck; the $37,250 super catch-up limit (ages 60-63) takes about $1,432.69. Starting mid-year with fewer pay periods left raises the per-paycheck amount needed to hit the same annual total, which is worth checking before assuming a flat percentage election will get you all the way to the max by December.</p>' ],
            [ 'Can you max out both a 401(k) and an IRA in 2027?', '<p>Yes — the two limits are entirely separate. A 61-year-old could contribute the full $37,250 to a 401(k) and also the full $8,600 to an IRA in the same year, for $45,850 in total tax-advantaged retirement savings, subject to income limits on IRA deductibility or Roth IRA eligibility. See our <a href="/retirement-planning-how-much-need-2026/">retirement planning guide</a> for how these pieces fit into an overall savings target.</p>' ],
            [ 'The contribution limit is not the same as being allowed to contribute at all', '<p>Most contribution-limit pages stop at the dollar amount, but for a Roth IRA specifically, your income can cut you off from contributing directly at any amount. For 2027, the Roth IRA eligibility phase-out is $158,000-$173,000 of modified AGI for single filers and heads of household, and $250,000-$260,000 for married filing jointly — below the range you can contribute the full limit, inside the range your allowed amount shrinks, and at or above the top of the range you cannot contribute to a Roth IRA directly at all that year. A Traditional IRA has no such income cap on the contribution itself (only on whether it is tax-deductible), so high earners locked out of a direct Roth contribution often use a Traditional IRA instead, or a "backdoor Roth" conversion strategy — a separate topic from the contribution limit itself.</p>' ],
            [ 'Can I contribute to my 2027 IRA before 2027 even starts?', '<p>No — IRA contributions are tied to a specific tax year, and you cannot designate a contribution for 2027 until January 1, 2027 at the earliest. What you can still do in late 2026 is make a prior-year contribution for 2026 itself, up until the 2026 tax filing deadline in April 2027 — many people confuse "making a contribution in early 2027" with "contributing for 2027," when it could actually still count toward 2026 if you say so when you contribute.</p>' ],
        ],
        'terms'     => [
            [ 'FICA wages', 'Your Social Security/Medicare taxable wages, shown in Box 3 of your W-2 — the figure used to test the $155,000 mandatory Roth catch-up threshold.' ],
            [ 'Super catch-up', 'The enhanced $11,750 catch-up contribution available only to 401(k)/403(b)/457/TSP participants aged 60, 61, 62, or 63.' ],
            [ 'Roth catch-up', 'A catch-up contribution made with after-tax dollars rather than pre-tax, mandatory for higher earners under SECURE 2.0.' ],
        ],
        'faqs'      => [
            [ 'What is the 401(k) contribution limit for 2027?', '$25,500 for employees under 50. With the age-50+ catch-up it is $34,000, and for ages 60-63 specifically, the enhanced catch-up brings the total to $37,250.' ],
            [ 'What is the IRA contribution limit for 2027?', '$7,500, or $8,600 if you are 50 or older. This limit applies across all your Traditional and Roth IRAs combined.' ],
            [ 'What is the age 60-63 super catch-up?', 'An enhanced $11,750 catch-up contribution (for 2027) available only to 401(k)/403(b)/governmental 457/TSP participants in the specific calendar years they are 60, 61, 62, or 63 — reverting to the standard $8,500 catch-up at 64.' ],
            [ 'Who has to make their catch-up contribution as Roth?', 'Anyone whose prior-year FICA wages (Box 3 of their W-2) exceeded $155,000 for 2027 must have their entire catch-up contribution designated as Roth (after-tax), with no pre-tax option, under SECURE 2.0 Section 603.' ],
            [ 'Does the $155,000 threshold use my current income or last year\'s?', 'Last year\'s FICA wages. The test looks backward at your prior-year W-2 Box 3 amount, not your current salary or this year\'s projected income.' ],
            [ 'Can I use the super catch-up in an IRA?', 'No. The enhanced 60-63 catch-up only applies to employer-sponsored plans (401(k), 403(b), governmental 457, TSP). IRAs get the standard $1,100 catch-up at age 50+ with no special boost at any age.' ],
            [ 'What happens to my catch-up when I turn 64?', 'It drops from the $11,750 super catch-up back down to the standard $8,500 catch-up amount, since the enhanced tier only applies through age 63.' ],
            [ 'Can I contribute to both a 401(k) and an IRA in 2027?', 'Yes, the limits are separate. You could contribute up to your full 401(k) limit and your full IRA limit in the same year, subject to income-based limits on IRA deductibility or Roth IRA eligibility.' ],
            [ 'What are the 2027 Roth IRA income limits?', 'The Roth IRA eligibility phase-out for 2027 is $158,000 to $173,000 of modified AGI for single filers and heads of household, and $250,000 to $260,000 for married filing jointly. Below the range you can contribute the full amount; above it, you cannot contribute directly at all.' ],
            [ 'Can I contribute to a 2027 IRA before 2027 starts?', 'No. You cannot designate a contribution for the 2027 tax year until January 1, 2027. Contributions made in early 2027 can still be designated for the 2026 tax year instead, up until the April 2027 filing deadline.' ],
            [ 'How much should I contribute each paycheck to max out my 401(k) in 2027?', 'Divide your total limit by the number of pay periods remaining in the year. For a biweekly payroll (26 periods) starting in January, the standard $34,000 limit works out to about $1,307.69 per paycheck, and the $37,250 super catch-up limit to about $1,432.69. Use the calculator above with your actual pay frequency and start date for an exact figure.' ],
        ],
        'sources'   => [
            [ 'IRS: Notice 2026-66, 2027 retirement plan limits', 'https://www.irs.gov/newsroom/401k-limit-increases-to-25500-for-2027-ira-limit-remains-7500' ],
            [ 'IRS: Retirement topics — catch-up contributions', 'https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-catch-up-contributions' ],
        ],
        'related'   => [ '401k-calculator', 'ira-calculator', 'retirement-savings-calculator', 'student-loan-401k-match-calculator' ],
    ],

    '2027-tax-bracket-calculator' => [
        'focus'     => '2027 tax bracket calculator',
        'secondary' => [ '2027 standard deduction', '2027 tax brackets', 'IRS Rev Proc 2026-35', '2027 Child Tax Credit', 'estimated 2027 federal tax' ],
        'title'     => '2027 Tax Bracket Calculator',
        'meta'      => 'Free 2027 tax bracket calculator: see your standard deduction, taxable income, marginal bracket, and estimated federal tax under IRS Rev. Proc. 2026-35.',
        'excerpt'   => 'Enter your income and filing status to see your 2027 standard deduction, taxable income, marginal tax bracket, and an estimate of what you will actually owe.',
        'answer'    => 'For 2027, the IRS set the standard deduction at $33,200 for married couples filing jointly, $16,600 for single filers and those married filing separately, and $24,925 for heads of household, per Rev. Proc. 2026-35. The seven tax rates stay at 10%, 12%, 22%, 24%, 32%, 35% and 37%, with the top 37% rate starting above $661,375 of taxable income for single filers and above $793,650 for married couples filing jointly. The Child Tax Credit rises to $2,300 per qualifying child.',
        'steps'     => [
            'Enter your income after pre-tax deductions (401(k), HSA) but before the standard deduction.',
            'Select your filing status: single, married filing jointly, married filing separately, or head of household.',
            'Check the boxes if you (or your spouse) will be 65 or older, or legally blind, in 2027 — this raises your standard deduction.',
            'Enter how many qualifying children under 17 you have for a quick Child Tax Credit estimate.',
            'See your standard deduction, taxable income, marginal bracket, effective rate, and estimated federal tax, broken out bracket by bracket below.',
        ],
        'formula'   => '<p><strong>Taxable income</strong> = income − standard deduction (plus any additional age-65/blind amounts).</p><p><strong>Tax owed</strong> is calculated bracket by bracket — each dollar of taxable income is taxed only at the rate for the bracket it falls in, not your whole income at your top rate. The calculator above runs this math automatically using the 2027 thresholds from IRS Rev. Proc. 2026-35.</p><p><strong>2027 standard deduction:</strong> $33,200 (MFJ), $16,600 (single or MFS), $24,925 (HoH). Additional amount for 65+/blind: $2,100 (single/HoH) or $1,700 per married person (MFJ/MFS), and the two stack if you qualify for both.</p>',
        'example'   => '<p>A single filer earning $85,000 after 401(k) and HSA contributions, under 65, not blind, no dependents:</p><ul><li>Standard deduction: <strong>$16,600</strong></li><li>Taxable income: $85,000 − $16,600 = <strong>$68,400</strong></li><li>Marginal bracket: <strong>22%</strong> (the last dollar earned falls in the 22% bracket, which for singles in 2027 runs from $52,026 to $109,125)</li><li>Tax is calculated in layers: 10% on the first $12,800, 12% on the next chunk up to $52,025, and 22% on the remainder up to $68,400 — not 22% on the whole $68,400</li><li>Estimated federal tax: roughly <strong>$9,700</strong>, for an effective rate of about <strong>11.4%</strong> of gross income — well below the 22% marginal rate</li></ul>',
        'sections'  => [
            [ 'Marginal rate and effective rate are not the same number', '<p>This is the single most common confusion in tax questions: your "tax bracket" (22%, say) only applies to the last layer of your income, not all of it. Every dollar below that layer is still taxed at the lower rates that came before it — 10% on the first slice, 12% on the next, and so on. That is why the effective rate the calculator shows (what you actually pay as a share of your income) is always lower than the marginal rate, often by quite a lot. Earning one more dollar and crossing into a higher bracket never reduces your take-home pay — it only raises the rate on dollars above the threshold, never the dollars below it.</p>' ],
            [ 'The 2027 standard deduction jump and what is driving it', '<p>The 2027 amounts ($33,200 MFJ, $16,600 single/MFS, $24,925 HoH) are set by Rev. Proc. 2026-35, the IRS\'s annual inflation-adjustment announcement released November 5, 2026. These are the baseline standard deduction figures under current law; they do not include the separate, flat $6,000 "senior bonus deduction" for filers 65 and older created by the 2025 tax law, which stacks on top of the regular standard deduction and the age-65 add-on covered here — see our <a href="/senior-deduction-calculator/">senior deduction calculator</a> for that piece specifically.</p>' ],
            [ 'Why married filing separately almost never beats married filing jointly', '<p>MFS brackets are set at exactly half of the MFJ thresholds through most of the table, and the standard deduction for MFS ($16,600) is also exactly half of the MFJ amount. In practice this means a married couple rarely comes out ahead filing separately on tax brackets alone — MFS exists mainly for specific situations like separating liability for a spouse\'s tax debt, income-driven student loan repayment calculations, or certain itemized deduction strategies, not as a way to lower a joint tax bill.</p>' ],
            [ 'What this estimate leaves out', '<p>This calculator estimates federal income tax only, using the standard deduction, the 2027 brackets, and the Child Tax Credit. It does not account for: itemized deductions (if they exceed your standard deduction, they would lower your taxable income further), the separate $6,000 senior deduction, the new no-tax-on-tips and no-tax-on-overtime deductions, the Earned Income Tax Credit or other credits, self-employment tax, the Net Investment Income Tax, or any state income tax. Treat the result as a solid starting estimate for federal tax only, not a finished return.</p>' ],
            [ 'How the Child Tax Credit estimate works here', '<p>The 2027 Child Tax Credit is $2,300 per qualifying child under 17 with a valid Social Security number. This calculator multiplies that figure by the number of children you enter as a simple ceiling — it does not apply the income phase-out (which reduces the credit for higher earners) or the cap on the refundable portion, both of which depend on details this tool does not collect. For most middle-income families the full amount applies, but higher earners should treat this line as an upper bound rather than a guaranteed number.</p>' ],
            [ 'Why the 35% bracket is unusually wide for 2027', '<p>Looking at the bracket table, the 35% bracket covers a huge range of income compared to the ones below it — from $264,551 to $661,375 for single filers. That is not a typo: the 10% through 32% brackets are relatively narrow and inflation-adjusted every year, while the top two brackets (35% and 37%) were set wide by the 2017 tax law and its 2025 extension, so a household earning $300,000 and one earning $600,000 can land in the exact same marginal bracket despite a huge income gap between them.</p>' ],
        ],
        'terms'     => [
            [ 'Marginal tax bracket', 'The tax rate that applies to your last dollar of taxable income — not the rate applied to your entire income.' ],
            [ 'Effective tax rate', 'Your total federal tax owed divided by your total income, expressed as a percentage — always lower than your marginal bracket.' ],
            [ 'Standard deduction', 'A flat dollar amount the IRS lets every filer subtract from income before calculating tax, without needing to itemize.' ],
            [ 'Qualifying child', 'For the Child Tax Credit, a dependent under age 17 at the end of the tax year with a valid Social Security number.' ],
        ],
        'faqs'      => [
            [ 'What is the 2027 standard deduction?', '$33,200 for married couples filing jointly, $16,600 for single filers and those married filing separately, and $24,925 for heads of household, per IRS Rev. Proc. 2026-35.' ],
            [ 'What are the 2027 tax brackets?', 'The seven rates stay at 10%, 12%, 22%, 24%, 32%, 35% and 37%. For single filers the 37% top rate starts above $661,375 of taxable income; for married couples filing jointly it starts above $793,650.' ],
            [ 'What is the extra standard deduction for being 65 or older in 2027?', '$2,100 for single filers and heads of household, and $1,700 per spouse for married filers (joint or separate). Being both 65+ and blind doubles the add-on for that person.' ],
            [ 'What is the 2027 Child Tax Credit amount?', '$2,300 per qualifying child under 17 with a valid Social Security number, subject to income phase-outs and a cap on the refundable portion.' ],
            [ 'Is my marginal tax bracket the rate I pay on all my income?', 'No. Only the portion of your taxable income that falls inside that top bracket is taxed at that rate — income in the lower brackets is still taxed at the lower rates for each of those bands.' ],
            [ 'Does this calculator include state income tax?', 'No, this tool estimates federal income tax only. Add your state\'s tax separately, since state brackets and deductions vary widely and some states have no income tax at all.' ],
            [ 'Why is married filing separately almost identical to single in the lower brackets?', 'The IRS sets MFS brackets at exactly half of the married-filing-jointly thresholds for most of the table, which happens to match the single-filer thresholds through the 32% bracket for 2027.' ],
            [ 'Does this tool account for itemized deductions?', 'No. It uses the standard deduction only. If your itemized deductions (mortgage interest, charitable gifts, state and local taxes up to the cap, etc.) exceed your standard deduction, your actual taxable income would be lower than this estimate shows.' ],
        ],
        'sources'   => [
            [ 'IRS: Tax inflation adjustments for tax year 2027', 'https://www.irs.gov/newsroom/irs-releases-tax-inflation-adjustments-for-tax-year-2027-taxpayers-continue-to-benefit-from-the-working-families-tax-cuts' ],
            [ 'IRS: Rev. Proc. 2026-35 (PDF)', 'https://www.irs.gov/pub/irs-drop/rp-26-35.pdf' ],
        ],
        'related'   => [ 'income-tax-calculator', 'child-tax-credit-calculator', 'salt-deduction-calculator', 'senior-deduction-calculator' ],
    ],

    'cardano-staking-calculator' => [
        'focus'     => 'cardano staking calculator',
        'secondary' => [ 'ADA staking rewards calculator', 'how much can you earn staking Cardano', 'Cardano staking APY', 'ADA delegation calculator', 'Cardano stake pool fees' ],
        'title'     => 'Cardano (ADA) Staking Calculator',
        'meta'      => 'Free Cardano staking calculator: estimate your ADA rewards, USD value, and effective APY after stake pool fees, with auto-compounding every epoch.',
        'excerpt'   => 'Enter how much ADA you plan to delegate to see your estimated staking rewards, their USD value, and your effective APY after stake pool fees.',
        'answer'    => 'Cardano (ADA) staking has recently paid roughly 2%-3% a year network-wide, based on StakingRewards.com data from early October 2026 — down from the 3%-4% many sources cited earlier in 2026, since the rate falls as more ADA gets staked. There is no minimum amount to delegate, and most stake pools charge a 0%-5% margin on top of a small fixed per-epoch fee, so your actual take-home rate depends on the pool you choose.',
        'steps'     => [
            'Enter how much ADA you plan to stake (delegate) — there is no minimum amount required.',
            'Enter the expected annual reward rate; the default reflects a recent network-wide estimate, but edit it if you are tracking a specific pool or a more current figure.',
            'Enter your chosen stake pool\'s margin/fee percentage.',
            'Enter today\'s ADA price in USD and how many months you plan to stake.',
            'Review your estimated ADA rewards, their USD value, your effective APY after fees, and how much extra you earn from automatic compounding.',
        ],
        'formula'   => '<p><strong>Net annual rate = gross reward rate x (1 − pool margin)</strong>.</p><p>Cardano pays rewards every epoch (a fixed <strong>5-day period</strong>, about 73 epochs a year) and automatically re-delegates them along with your original stake, so your balance compounds roughly every 5 days rather than once a year: <strong>per-epoch rate = net annual rate / 73</strong>, and <strong>final ADA = staked ADA × (1 + per-epoch rate)^(number of epochs)</strong>. The effective APY shown is what that epoch-by-epoch compounding works out to over a full year.</p>',
        'example'   => '<p>Staking 1,000 ADA for 12 months at a 3% gross annual reward rate through a pool with a 2% margin:</p><ul><li>Net annual rate: 3% × (1 − 2%) ≈ <strong>2.94%</strong></li><li>Spread across roughly 73 epochs and compounded each time, that works out to an effective APY of about <strong>2.98%</strong> — slightly higher than the simple net rate, because of compounding</li><li>Estimated rewards after one year: roughly <strong>29.8 ADA</strong></li><li>At an example price of $0.45/ADA, that is about <strong>$13.40</strong> in rewards for the year</li></ul><p>Rewards and ADA price both move constantly — rerun the calculator with your pool\'s actual margin and the current ADA price for a live estimate.</p>',
        'sections'  => [
            [ 'There is no minimum amount of ADA to stake', '<p>Unlike Ethereum, where running your own validator requires locking up 32 ETH, Cardano has no minimum delegation amount at all. You delegate your ADA to an existing stake pool — you never send the pool your coins, you keep full custody in your own wallet, and you can stake anywhere from a few ADA to a large holding through the same process. This is one of the most beginner-friendly features of Cardano\'s proof-of-stake design.</p>' ],
            [ 'Why the reward rate keeps drifting lower', '<p>Cardano\'s protocol reward rate is not a fixed number set by anyone — it depends on how much of the total ADA supply is actively staked across the network. As more ADA gets delegated, the same pool of rewards gets split among more participants, so the rate per staker drifts down. StakingRewards.com measured Cardano\'s actual reward rate at roughly 2.1%-2.7% in early October 2026, lower than the 3%-4% figures some sources were citing earlier in the year, reflecting exactly this dynamic. Always check a live source rather than relying on an older published number.</p>' ],
            [ 'How stake pool fees actually work', '<p>Every Cardano stake pool sets two separate costs: a small <strong>fixed fee per epoch</strong> (a protocol-level minimum, commonly around 170 ADA, that covers the pool operator\'s running costs and is deducted before rewards are split) and a <strong>variable margin</strong>, typically 0%-5% of the remaining rewards, that the operator keeps as their profit. A pool advertising "0% margin" still takes the fixed per-epoch fee — it just skips the extra percentage cut. Compare a few pools\' published margins before delegating, since a 1-2 percentage point difference compounds meaningfully over several years.</p>' ],
            [ 'Rewards compound automatically — you do not have to do anything', '<p>Unlike a savings account where you might have to manually reinvest interest, Cardano epoch rewards are automatically added to your delegated stake, so next epoch\'s reward calculation already includes the ADA you just earned. This is true "set it and forget it" compounding, paid out every 5-day epoch instead of once a year, which is why the calculator above shows a slightly higher effective APY than the plain net rate you entered.</p>' ],
            [ 'Your ADA stays liquid the whole time', '<p>Staking on Cardano involves no lock-up period and no slashing risk for the delegator. You can switch pools, stop delegating, or spend your ADA at any time — a change in delegation typically takes effect after one to two epochs (roughly 5-10 days) rather than instantly, but there is no penalty or waiting period like some other proof-of-stake networks require for unstaking.</p>' ],
        ],
        'terms'     => [
            [ 'Delegation', 'Assigning your ADA\'s staking weight to a stake pool without transferring custody — you keep your coins in your own wallet the whole time.' ],
            [ 'Epoch', 'Cardano\'s fixed 5-day accounting period; staking rewards are calculated and paid out once per epoch.' ],
            [ 'Stake pool margin', 'The percentage of rewards a pool operator keeps as profit, on top of a small fixed per-epoch fee.' ],
            [ 'Saturation', 'The point at which a stake pool has attracted so much delegated ADA that rewards per delegator start to shrink, encouraging delegators to spread stake across pools.' ],
        ],
        'faqs'      => [
            [ 'How much can you earn staking Cardano?', 'Recently, roughly 2%-3% a year network-wide before pool fees, based on StakingRewards.com data from early October 2026. Your actual return depends on your pool\'s margin and how much total ADA is staked across the network at the time, so treat any single number as an estimate that changes.' ],
            [ 'Is there a minimum amount of ADA required to stake?', 'No. Cardano has no minimum delegation amount — you can stake any amount of ADA through a stake pool, unlike Ethereum, which requires 32 ETH to run a solo validator.' ],
            [ 'How often are Cardano staking rewards paid?', 'Once per epoch, a fixed 5-day period, which works out to roughly 73 times a year. Rewards are automatically re-delegated with your existing stake, so they compound without any action on your part.' ],
            [ 'Do I lose custody of my ADA when I stake it?', 'No. Delegating assigns your stake\'s voting/reward weight to a pool, but your ADA stays in your own wallet the entire time — the pool never takes custody of your coins.' ],
            [ 'What fees do Cardano stake pools charge?', 'Most pools charge a small fixed per-epoch fee (commonly around 170 ADA, a protocol-level minimum) plus a variable margin, typically 0%-5% of the remaining rewards, which the pool operator keeps.' ],
            [ 'Can I unstake my ADA at any time?', 'Yes. There is no lock-up period or penalty for changing or stopping delegation, though a change typically takes effect after one to two epochs (about 5-10 days), not instantly.' ],
            [ 'Why does my actual staking rate look lower than a figure I saw months ago?', 'Cardano\'s reward rate depends on the total ADA staked network-wide — as more ADA gets delegated over time, the rate per staker tends to drift down. Check a live source like StakingRewards.com for the current figure rather than an older article.' ],
        ],
        'sources'   => [
            [ 'StakingRewards.com: Cardano (ADA) overview', 'https://www.stakingrewards.com/earn/cardano/overview' ],
            [ 'Cardano Docs: Delegating and stake pools', 'https://docs.cardano.org/about-cardano/explore-more/stake-pools/' ],
        ],
        'related'   => [ 'staking-rewards-calculator', 'crypto-pl-calculator', 'crypto-converter' ],
    ],

    'polkadot-staking-calculator' => [
        'focus'     => 'polkadot staking calculator',
        'secondary' => [ 'DOT staking rewards calculator', 'how much can you earn staking Polkadot', 'Polkadot staking APY', 'Polkadot unbonding period', 'DOT nominator minimum bond' ],
        'title'     => 'Polkadot (DOT) Staking Calculator',
        'meta'      => 'Free Polkadot staking calculator: estimate your DOT rewards, USD value, and effective APY after commission — plus the 28-day unbonding period you need to plan around.',
        'excerpt'   => 'Enter how much DOT you plan to stake to see your estimated rewards, their USD value, your effective APY after commission, and the unbonding wait if you ever want it back.',
        'answer'    => 'Polkadot staking has recently paid roughly 2.8%-5.4% a year depending on the source and route you use (Kraken and CoinStats data, Oct-Nov 2026), after Polkadot moved to a new, lower inflation model in 2024-2025. Nomination pools let you start with as little as 1 DOT, while nominating a validator directly needs a dynamic minimum bond that moves every era. The number that trips people up most is the unbonding period: once you stop staking, it takes a fixed 28 days to get your DOT back, and it keeps earning nothing while you wait.',
        'steps'     => [
            'Enter how much DOT you plan to stake — through a nomination pool (minimum as low as 1 DOT) or by nominating a validator directly (a higher, dynamic minimum).',
            'Enter the expected annual reward rate; the default reflects a recent estimate, but edit it if you are tracking a specific validator, pool, or a more current figure from your staking dashboard.',
            'Enter the validator or nomination pool\'s commission percentage.',
            'Enter today\'s DOT price in USD and how many months you plan to stake.',
            'Review your estimated DOT rewards, their USD value, your effective APY after commission, and the 28-day unbonding period you would face if you decide to stop.',
        ],
        'formula'   => '<p><strong>Net annual rate = gross reward rate x (1 − validator/pool commission)</strong>.</p><p>Polkadot pays staking rewards once per <strong>era</strong> (a fixed 24-hour period, so about 365 eras a year), but unlike Cardano, rewards for a direct nominator are credited to your free balance and are not automatically re-staked — you have to manually bond them again to compound. This calculator therefore uses simple, non-compounding interest as the realistic default: <strong>estimated DOT rewards = staked DOT × net annual rate × (months / 12)</strong>. If you use a nomination pool with auto-compounding enabled, or manually re-bond every reward, your real total would run a little higher than this estimate.</p>',
        'example'   => '<p>Staking 100 DOT for 12 months at a 4.5% gross annual reward rate through a validator charging 5% commission:</p><ul><li>Net annual rate: 4.5% × (1 − 5%) ≈ <strong>4.28%</strong></li><li>Estimated rewards after one year: roughly <strong>4.28 DOT</strong></li><li>At an example price of $4.00/DOT, that is about <strong>$17.10</strong> in rewards for the year</li><li>If you decided to stop staking at that point, you would wait <strong>28 days</strong> before that 100+ DOT became spendable again</li></ul><p>Reward rates, commissions, and DOT\'s price all move — rerun the calculator with your validator or pool\'s actual numbers and the current DOT price for a live estimate.</p>',
        'sections'  => [
            [ 'The unbonding period is the single biggest thing to plan around', '<p>Polkadot has one of the longest unbonding periods of any major proof-of-stake network: a fixed <strong>28 days</strong> from the moment you ask to unstake to the moment your DOT is spendable again. There is no way to speed this up once it starts (though you can usually cancel and re-bond if you change your mind partway through), and your DOT earns zero reward during the wait. Compare that to Cardano, which has no lock-up at all, or Solana\'s cooldown of just a few days — if there is any chance you will need this money on short notice, the 28-day wait should factor into how much you stake in the first place.</p>' ],
            [ 'Two ways to stake: nomination pools vs. direct nomination', '<p>Most everyday holders use a <strong>nomination pool</strong>, which lets you join with as little as 1 DOT and pools your stake together with other members behind a set of validators someone else manages. Nominating a validator <strong>directly</strong> gives you more control (you pick up to 16 validators yourself) but requires a much higher, dynamic minimum bond that moves every era with overall network demand — it has recently sat in the low hundreds of DOT, so check the live figure on the staking dashboard before assuming you qualify.</p>' ],
            [ 'Polkadot\'s 2024-2025 inflation change lowered and steadied the rate', '<p>Polkadot moved to a new tokenomics and inflation model in 2024-2025 that shifted away from its older, higher-inflation design toward a lower, more capped issuance schedule. One practical effect is that the staking reward rate you will see quoted today is noticeably different from older pre-2024 articles — current estimates have ranged from roughly 2.8% to 5.4% across different sources measured in late 2026, rather than the higher double-digit figures sometimes cited from years earlier. Always check a live source rather than trusting an old number.</p>' ],
            [ 'Rewards are not auto-compounded the way Cardano\'s are', '<p>Each era (a fixed 24-hour period), the protocol calculates and pays out rewards — but for a direct nominator, those rewards simply add to your free, unstaked balance. They do not automatically get bonded back into your stake the way Cardano\'s epoch rewards do. If you want compounding, you need to either manually bond your rewards again or use a nomination pool with auto-compounding turned on. This calculator defaults to simple, non-compounding interest to reflect what actually happens if you do nothing extra.</p>' ],
            [ 'Commission rates vary a lot between validators and pools', '<p>Every validator and nomination pool sets its own commission, and there is real variation — some charge 0%, many sit in the 1%-10% range, and a few charge more. A validator with great uptime but high commission can net you less than a cheaper one with slightly worse (but still solid) performance. Check the specific commission and recent performance of whoever you are nominating before committing, rather than assuming all validators pay similarly.</p>' ],
        ],
        'terms'     => [
            [ 'Era', 'Polkadot\'s fixed 24-hour accounting period; staking rewards are calculated and distributed once per era.' ],
            [ 'Nominator', 'A DOT holder who backs one or more validators with their stake (directly or through a pool) in exchange for a share of that validator\'s rewards.' ],
            [ 'Nomination pool', 'A way to stake with a small amount of DOT (as little as 1 DOT) by pooling your stake with other members behind a shared set of validators.' ],
            [ 'Unbonding period', 'The fixed 28-day wait between requesting to stop staking and your DOT actually becoming spendable again.' ],
        ],
        'faqs'      => [
            [ 'How much can you earn staking Polkadot?', 'Recently, estimates have ranged from roughly 2.8% to 5.4% a year before commission, depending on the source and when it was measured (Kraken and CoinStats data, Oct-Nov 2026). Your actual return depends on your validator or pool\'s commission and the live network rate, so treat any single number as an estimate that changes.' ],
            [ 'What is the minimum amount of DOT needed to stake?', 'It depends on the route: nomination pools let you join with as little as 1 DOT, while nominating a validator directly requires a much higher, dynamic minimum that moves every era with network demand — check your staking dashboard for the current figure before assuming you qualify.' ],
            [ 'How long is Polkadot\'s unbonding period?', 'A fixed 28 days. Once you ask to stop staking, your DOT earns nothing and cannot be withdrawn until those 28 days pass — one of the longest unbonding periods of any major proof-of-stake network.' ],
            [ 'Do Polkadot staking rewards automatically compound?', 'Not for direct nominators by default — rewards land in your free balance each era but are not auto-restaked. You would need to manually re-bond them, or use a nomination pool with auto-compounding enabled, to actually compound your returns.' ],
            [ 'What is a Polkadot era?', 'A fixed 24-hour period — Polkadot\'s basic unit for calculating and paying out staking rewards, so there are roughly 365 eras a year.' ],
            [ 'Can I cancel an unbonding request partway through?', 'Generally yes — most wallets and the staking dashboard let you re-bond DOT that is still mid-unbonding if you change your mind, but once the full 28 days pass and you withdraw, you would need to start a new unbonding cycle to stake again later.' ],
            [ 'How does Polkadot\'s yield compare to Cardano, Ethereum, or Solana?', 'Polkadot\'s roughly 2.8%-5.4% range is broadly similar to Ethereum\'s ~3%-4% and above Cardano\'s ~2%-3%, but below Solana\'s ~6%-7% — though Polkadot\'s 28-day unbonding period is far longer than any of theirs, which is a real tradeoff against the yield.' ],
        ],
        'sources'   => [
            [ 'Kraken: Polkadot staking rewards explained', 'https://www.kraken.com/learn/polkadot-staking-rewards-explained' ],
            [ 'CoinStats: Polkadot staking data', 'https://coinstats.app/news/a97323b6a737cbe224221deaf27a1ae84f9dc00752afbf40cb556a0dbec0741d_28-Days-Locked-for-277-Percent-a-Year-What-Polkadot-Staking-Means-for-Your-DOT/' ],
            [ 'Polkadot Wiki: Staking basics and parameters', 'https://wiki.polkadot.network/docs/learn-staking-advanced' ],
        ],
        'related'   => [ 'cardano-staking-calculator', 'staking-rewards-calculator', 'crypto-pl-calculator', 'crypto-converter' ],
